/**
 * Given a list of integers and a target sum, returns the indices of
 * the two numbers that add up to the target.
 *
 * Uses a hash map for O(n) time complexity.
 */
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) {
      return [seen.get(complement), i];
    }
    seen.set(nums[i], i);
  }
  return null;
}

// --------------- Tests ---------------

function assert(condition, message) {
  if (!condition) throw new Error(`FAIL: ${message}`);
  console.log(`PASS: ${message}`);
}

// Basic case
assert(
  JSON.stringify(twoSum([2, 7, 11, 15], 9)) === JSON.stringify([0, 1]),
  "basic: [2,7,11,15] target 9 -> [0,1]"
);

// Pair in the middle
assert(
  JSON.stringify(twoSum([1, 3, 5, 7, 9], 12)) === JSON.stringify([2, 4]),
  "mid-pair: [1,3,5,7,9] target 12 -> [2,4]"
);

// Pair at the ends
assert(
  JSON.stringify(twoSum([3, 2, 4], 6)) === JSON.stringify([1, 2]),
  "end-pair: [3,2,4] target 6 -> [1,2]"
);

// Negative numbers
assert(
  JSON.stringify(twoSum([-1, -2, -3, -4, -5], -8)) === JSON.stringify([2, 4]),
  "negatives: [-1,-2,-3,-4,-5] target -8 -> [2,4]"
);

// Mixed positive and negative
assert(
  JSON.stringify(twoSum([1, -2, 3, 5, -7], -9)) === JSON.stringify([1, 4]),
  "mixed: [1,-2,3,5,-7] target -9 -> [1,4]"
);

// Zero in the list
assert(
  JSON.stringify(twoSum([0, 4, 3, 0], 0)) === JSON.stringify([0, 3]),
  "zeros: [0,4,3,0] target 0 -> [0,3]"
);

// Duplicate values
assert(
  JSON.stringify(twoSum([3, 3], 6)) === JSON.stringify([0, 1]),
  "duplicates: [3,3] target 6 -> [0,1]"
);

// No solution
assert(
  twoSum([1, 2, 3], 100) === null,
  "no solution: [1,2,3] target 100 -> null"
);

// Single element (no pair possible)
assert(
  twoSum([5], 5) === null,
  "single element: [5] target 5 -> null"
);

// Empty list
assert(
  twoSum([], 0) === null,
  "empty list: [] target 0 -> null"
);

// Large values
assert(
  JSON.stringify(twoSum([1000000, 500000, -1500000, 3], -500000)) === JSON.stringify([0, 2]),
  "large values: [1000000,500000,-1500000,3] target -500000 -> [0,2]"
);

console.log("\nAll tests passed.");
